macro_rules! map_of {
    (0, $descriptor:literal) => {
        method("of", $descriptor, ACC_PUBLIC | ACC_STATIC, |vm, _, _| {
            map_of_pairs(vm, &[])
        })
    };
    ($arg_count:expr, $descriptor:literal) => {
        method("of", $descriptor, ACC_PUBLIC | ACC_STATIC, |vm, _, args| {
            let mut pairs = Vec::with_capacity($arg_count / 2);
            let mut index = 0;
            while index < $arg_count {
                pairs.push((ref_arg(args, index), ref_arg(args, index + 1)));
                index += 2;
            }
            map_of_pairs(vm, &pairs)
        })
    };
}

/// Invoke a map operation on `this` via virtual dispatch (used by the `Map` default methods).
fn map_invoke(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    name: &str,
    descriptor: &str,
    extra: &[Value],
) -> Result<Value, VmError> {
    let (class, method) = vm.resolve_virtual_method(this, name, descriptor)?;
    let mut args = vec![Value::Ref(this)];
    args.extend_from_slice(extra);
    vm.invoke_method(class, method, args)
}

