macro_rules! array_equals {
    ($descriptor:literal) => {
        method(
            "equals",
            $descriptor,
            ACC_PUBLIC | ACC_STATIC,
            |vm, _, args| {
                let a = ref_arg(args, 0);
                let b = ref_arg(args, 1);
                boolean(a == b || arrays_equal(vm, a, b)?)
            },
        )
    };
}

macro_rules! array_copy_of {
    ($descriptor:literal) => {
        method(
            "copyOf",
            $descriptor,
            ACC_PUBLIC | ACC_STATIC,
            arrays_copy_of_objects,
        )
    };
}

macro_rules! array_copy_of_range {
    ($descriptor:literal) => {
        method(
            "copyOfRange",
            $descriptor,
            ACC_PUBLIC | ACC_STATIC,
            arrays_copy_of_range_objects,
        )
    };
}

macro_rules! array_mismatch {
    ($descriptor:literal) => {
        method(
            "mismatch",
            $descriptor,
            ACC_PUBLIC | ACC_STATIC,
            |vm, _, args| int(arrays_mismatch(vm, ref_arg(args, 0), ref_arg(args, 1))?),
        )
    };
}

macro_rules! array_compare {
    ($name:literal, $descriptor:literal, $mask:expr) => {
        method(
            $name,
            $descriptor,
            ACC_PUBLIC | ACC_STATIC,
            |vm, _, args| {
                int(arrays_compare(
                    vm,
                    ref_arg(args, 0),
                    ref_arg(args, 1),
                    $mask,
                    ObjectRef::NULL,
                )?)
            },
        )
    };
}

macro_rules! array_compare_range {
    ($name:literal, $descriptor:literal, $mask:expr) => {
        method(
            $name,
            $descriptor,
            ACC_PUBLIC | ACC_STATIC,
            |vm, _, args| {
                int(arrays_compare_range(
                    vm,
                    ref_arg(args, 0),
                    int_arg(args, 1),
                    int_arg(args, 2),
                    ref_arg(args, 3),
                    int_arg(args, 4),
                    int_arg(args, 5),
                    $mask,
                    ObjectRef::NULL,
                )?)
            },
        )
    };
}

macro_rules! array_hash_code {
    ($descriptor:literal, $component:expr) => {
        method(
            "hashCode",
            $descriptor,
            ACC_PUBLIC | ACC_STATIC,
            |vm, _, args| int(arrays_hash_code(vm, ref_arg(args, 0), $component)?),
        )
    };
}

/// Shared implementation of `Arrays.setAll`/`parallelSetAll`: `kind` selects the generator
/// signature (0 = IntUnaryOperator, 1 = IntToLongFunction, 2 = IntToDoubleFunction,
/// 3 = IntFunction).
fn arrays_set_all(
    vm: &mut Vm<'_>,
    array: ObjectRef,
    generator: ObjectRef,
    kind: u8,
) -> Result<Value, VmError> {
    if array.is_null() || generator.is_null() {
        return Err(vm.throw_new("java/lang/NullPointerException", None));
    }
    let len = vm.array_length(array)?;
    let (class, method) = match kind {
        0 => vm.resolve_virtual_method(generator, "applyAsInt", "(I)I")?,
        1 => vm.resolve_virtual_method(generator, "applyAsLong", "(I)J")?,
        2 => vm.resolve_virtual_method(generator, "applyAsDouble", "(I)D")?,
        _ => vm.resolve_virtual_method(generator, "apply", "(I)Ljava/lang/Object;")?,
    };
    for index in 0..len {
        let result = vm.invoke_method(
            class,
            method,
            vec![Value::Ref(generator), Value::Int(index as i32)],
        )?;
        let value = match kind {
            0 => Value::Int(result.as_int()),
            1 => Value::Long(result.as_long()),
            2 => Value::Double(result.as_double()),
            _ => Value::Ref(result.as_ref()),
        };
        vm.array_set(array, index as i32, value, kind == 3)?;
    }
    void()
}

