/// The JDK's global seed uniquifier: an LCG advanced on every no-arg Random()
/// construction so instances created in the same nanosecond still differ.
fn random_seed_uniquifier() -> i64 {
    use core::sync::atomic::{AtomicU64, Ordering};
    static UNIQUIFIER: AtomicU64 = AtomicU64::new(8682522807148012);
    let mut current = UNIQUIFIER.load(Ordering::Relaxed);
    loop {
        let next = current.wrapping_mul(1181783497276652981);
        match UNIQUIFIER.compare_exchange_weak(current, next, Ordering::Relaxed, Ordering::Relaxed)
        {
            Ok(_) => return next as i64,
            Err(actual) => current = actual,
        }
    }
}

fn random_init(
    vm: &mut Vm<'_>,
    _c: oxjvm_vm::NativeContext,
    args: &[Value],
) -> Result<Value, VmError> {
    let seed = random_seed_uniquifier() ^ vm.host_nano_time();
    set_random_seed(vm, receiver(args), seed);
    void()
}

fn random_init_seed(
    vm: &mut Vm<'_>,
    _c: oxjvm_vm::NativeContext,
    args: &[Value],
) -> Result<Value, VmError> {
    set_random_seed(vm, receiver(args), long_arg(args, 1));
    void()
}

fn set_random_seed(vm: &mut Vm<'_>, this: ObjectRef, seed: i64) {
    let scrambled = (seed ^ 0x5DEECE66D) & ((1i64 << 48) - 1);
    write_random_seed(vm, this, scrambled);
}

fn read_random_seed(vm: &Vm<'_>, this: ObjectRef) -> i64 {
    match vm.heap.get(this).map(|object| &object.data) {
        Some(ObjectData::Instance(fields)) if !fields.is_empty() => fields[0].as_long(),
        _ => 0,
    }
}

fn write_random_seed(vm: &mut Vm<'_>, this: ObjectRef, seed: i64) {
    let class = vm.class_of(this);
    if let Some((declaring, field)) = vm.find_field_opt(class, "seed", "J") {
        let slot = vm.classes.get(declaring).fields[field as usize].slot as usize;
        if let Some(ObjectData::Instance(fields)) =
            vm.heap.get_mut(this).map(|object| &mut object.data)
        {
            fields[slot] = Value::Long(seed);
        }
    }
}

/// A uniformly distributed value in `[0, bound)` (the JDK rejection loop).
fn next_random_bounded(vm: &mut Vm<'_>, this: ObjectRef, bound: i32) -> Result<i32, VmError> {
    if bound & (bound - 1) == 0 {
        let bits = next_random_int(vm, this, 31, &[])?.as_int();
        return Ok(((i64::from(bound) * i64::from(bits)) >> 31) as i32);
    }
    loop {
        let bits = next_random_int(vm, this, 31, &[])?.as_int();
        let value = bits.rem_euclid(bound);
        if bits - value + (bound - 1) >= 0 {
            return Ok(value);
        }
    }
}

/// Materialized length of an infinite random stream, matching the eager-stream cap used by
/// the other unbounded sources.
const RANDOM_STREAM_CAP: usize = 1024;

pub(crate) fn random_stream_count(vm: &mut Vm<'_>, size: i64) -> Result<usize, VmError> {
    if size < 0 {
        return Err(vm.throw_new(
            "java/lang/IllegalArgumentException",
            Some("size must be non-negative"),
        ));
    }
    Ok(size as usize)
}

fn random_next_long(vm: &mut Vm<'_>, this: ObjectRef) -> Result<i64, VmError> {
    let high = next_random_int(vm, this, 32, &[])?.as_int();
    let low = next_random_int(vm, this, 32, &[])?.as_int();
    Ok(((high as i64) << 32).wrapping_add(i64::from(low)))
}

fn random_next_double(vm: &mut Vm<'_>, this: ObjectRef) -> Result<f64, VmError> {
    let high = next_random_int(vm, this, 26, &[])?.as_int();
    let low = next_random_int(vm, this, 27, &[])?.as_int();
    let value = ((high as i64) << 27).wrapping_add(i64::from(low));
    Ok(value as f64 / (1i64 << 53) as f64)
}

/// JDK `Random.nextLong(origin, bound)`: power-of-two masking, otherwise unsigned rejection.
fn random_bounded_long(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    origin: i64,
    bound: i64,
) -> Result<i64, VmError> {
    let n = bound.wrapping_sub(origin);
    if n <= 0 {
        loop {
            let r = random_next_long(vm, this)?;
            if r >= origin && r < bound {
                return Ok(r);
            }
        }
    }
    let m = n - 1;
    let mut r = random_next_long(vm, this)?;
    if (n & m) == 0 {
        r &= m;
    } else {
        let mut u = (r as u64) >> 1;
        loop {
            r = (u % n as u64) as i64;
            let check = u.wrapping_add(m as u64).wrapping_sub(r as u64);
            if check < (1u64 << 63) {
                break;
            }
            u = (random_next_long(vm, this)? as u64) >> 1;
        }
    }
    Ok(r.wrapping_add(origin))
}

fn random_bounded_double(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    origin: f64,
    bound: f64,
) -> Result<f64, VmError> {
    let unit = random_next_double(vm, this)?;
    let mut result = origin + unit * (bound - origin);
    if result >= bound || result.is_nan() {
        result = f64::from_bits(bound.to_bits() - 1);
    }
    Ok(result)
}

/// The next double toward positive infinity (`Math.nextUp`).
fn equi_next_up(x: f64) -> f64 {
    if x.is_nan() || x == f64::INFINITY {
        return x;
    }
    if x == 0.0 {
        return f64::from_bits(1);
    }
    if x > 0.0 {
        f64::from_bits(x.to_bits() + 1)
    } else {
        f64::from_bits(x.to_bits() - 1)
    }
}

/// The next double toward negative infinity (`Math.nextDown`).
fn equi_next_down(x: f64) -> f64 {
    if x.is_nan() || x == f64::NEG_INFINITY {
        return x;
    }
    if x == 0.0 {
        return f64::from_bits((1u64 << 63) | 1);
    }
    if x < 0.0 {
        f64::from_bits(x.to_bits() + 1)
    } else {
        f64::from_bits(x.to_bits() - 1)
    }
}

/// `RandomGenerator.equiDoubles`: equidistant doubles in an interval, after Goualard (2022).
/// Every value is an exact multiple `k * delta` of a power-of-two step.
pub(crate) fn random_equi_doubles(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    left: f64,
    right: f64,
    left_included: bool,
    right_included: bool,
) -> Result<Value, VmError> {
    let lo = if left_included {
        left
    } else {
        equi_next_up(left)
    };
    let hi = if right_included {
        right
    } else {
        equi_next_down(right)
    };
    if !(left.is_finite() && right.is_finite() && lo <= hi) {
        return Err(vm.throw_new(
            "java/lang/IllegalArgumentException",
            Some("the boundaries must be finite and the interval must not be empty"),
        ));
    }
    let sign_of = |x: f64| x.to_bits() & (1u64 << 63);
    let (delta, kl, kr) = if left <= -right {
        let delta = equi_next_up(left) - left;
        let rd = right / delta;
        let crd = if rd != 0.0 || right == 0.0 {
            rd
        } else {
            f64::from_bits(sign_of(right) | 1)
        };
        let kr = if right_included {
            crate::math::floor(crd) as i64 + 1
        } else {
            crate::math::ceil(crd) as i64
        };
        let kl = (left / delta) as i64 + i64::from(!left_included);
        (delta, kl, kr)
    } else {
        let delta = right - equi_next_down(right);
        let ld = left / delta;
        let cld = if ld != 0.0 || left == 0.0 {
            ld
        } else {
            f64::from_bits(sign_of(left) | 1)
        };
        let kl = if left_included {
            crate::math::ceil(cld) as i64
        } else {
            crate::math::floor(cld) as i64 + 1
        };
        let kr = (right / delta) as i64 + i64::from(right_included);
        (delta, kl, kr)
    };
    let n = kr - kl;
    let mut values = Vec::with_capacity(RANDOM_STREAM_CAP);
    for _ in 0..RANDOM_STREAM_CAP {
        let k = kl.wrapping_add(random_bounded_long(vm, this, 0, n)?);
        values.push(k as f64 * delta);
    }
    object(crate::primitive_stream::new_double_stream(vm, values)?)
}

pub(crate) fn random_int_stream(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    count: usize,
    range: Option<(i32, i32)>,
) -> Result<Value, VmError> {
    let mut values = Vec::with_capacity(count.min(RANDOM_STREAM_CAP));
    for _ in 0..count {
        let value = match range {
            None => next_random_int(vm, this, 32, &[])?.as_int(),
            Some((origin, bound)) => {
                origin.wrapping_add(next_random_bounded(vm, this, bound.wrapping_sub(origin))?)
            }
        };
        values.push(value);
    }
    object(crate::intstream::int_stream_from(vm, values)?)
}

pub(crate) fn random_long_stream(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    count: usize,
    range: Option<(i64, i64)>,
) -> Result<Value, VmError> {
    let mut values = Vec::with_capacity(count.min(RANDOM_STREAM_CAP));
    for _ in 0..count {
        let value = match range {
            None => random_next_long(vm, this)?,
            Some((origin, bound)) => random_bounded_long(vm, this, origin, bound)?,
        };
        values.push(value);
    }
    object(crate::primitive_stream::new_long_stream(vm, values)?)
}

pub(crate) fn random_double_stream(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    count: usize,
    range: Option<(f64, f64)>,
) -> Result<Value, VmError> {
    let mut values = Vec::with_capacity(count.min(RANDOM_STREAM_CAP));
    for _ in 0..count {
        let value = match range {
            None => random_next_double(vm, this)?,
            Some((origin, bound)) => random_bounded_double(vm, this, origin, bound)?,
        };
        values.push(value);
    }
    object(crate::primitive_stream::new_double_stream(vm, values)?)
}

fn random_int_range(vm: &mut Vm<'_>, origin: i32, bound: i32) -> Result<(i32, i32), VmError> {
    if bound <= origin {
        return Err(vm.throw_new(
            "java/lang/IllegalArgumentException",
            Some("bound must be greater than origin"),
        ));
    }
    Ok((origin, bound))
}

fn random_long_range(vm: &mut Vm<'_>, origin: i64, bound: i64) -> Result<(i64, i64), VmError> {
    if bound <= origin {
        return Err(vm.throw_new(
            "java/lang/IllegalArgumentException",
            Some("bound must be greater than origin"),
        ));
    }
    Ok((origin, bound))
}

fn random_double_range(vm: &mut Vm<'_>, origin: f64, bound: f64) -> Result<(f64, f64), VmError> {
    if origin >= bound || origin.is_nan() || bound.is_nan() {
        return Err(vm.throw_new(
            "java/lang/IllegalArgumentException",
            Some("bound must be greater than origin"),
        ));
    }
    Ok((origin, bound))
}

pub(crate) fn next_random_int(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    bits: i32,
    _bound: &[i32],
) -> Result<Value, VmError> {
    let mut seed = read_random_seed(vm, this);
    seed = seed.wrapping_mul(0x5DEECE66D).wrapping_add(0xB) & ((1i64 << 48) - 1);
    write_random_seed(vm, this, seed);
    Ok(Value::Int((seed >> (48 - bits)) as i32))
}

/// `java.util.RandomAccess`: a marker interface.
pub(crate) const RANDOM_ACCESS: oxjvm_vm::NativeClass = class(
    "java/util/RandomAccess",
    Some("java/lang/Object"),
    &[],
    ACC_PUBLIC | ACC_INTERFACE | ACC_ABSTRACT,
    &[],
    &[],
    None,
);

pub(crate) const RANDOM: oxjvm_vm::NativeClass = class(
    "java/util/Random",
    Some("java/lang/Object"),
    &["java/io/Serializable", "java/util/random/RandomGenerator"],
    ACC_PUBLIC,
    &[field("seed", "J", ACC_PRIVATE, None)],
    &RANDOM_METHODS,
    None,
);

