/// `AbstractList.indexOf`: the first index whose element equals `target`, or -1.
fn abstract_list_index_of(
    vm: &mut Vm<'_>,
    list: ObjectRef,
    target: ObjectRef,
    last: bool,
) -> Result<i32, VmError> {
    // An immutable list (or a sub-list view of one) is null-hostile.
    if target.is_null() && crate::lang::read_int_field(vm, list, "immutable") != 0 {
        return Err(vm.throw_new("java/lang/NullPointerException", None));
    }
    let size = invoke_int(vm, list, "size")?;
    let indices: Vec<i32> = if last {
        (0..size).rev().collect()
    } else {
        (0..size).collect()
    };
    for index in indices {
        let element = invoke_object(vm, list, "get", &[Value::Int(index)])?;
        if objects_equals(vm, element, target)? {
            return Ok(index);
        }
    }
    Ok(-1)
}

