fn bitset_words(vm: &mut Vm<'_>, this: ObjectRef) -> Vec<u64> {
    match vm.read_ref_field(this, vm.class_of(this), "words", "[J") {
        Some(array) => {
            let length = vm.array_length(array).unwrap_or(0);
            let mut words = Vec::with_capacity(length);
            let mut reads = Vec::with_capacity(length);
            for index in 0..length {
                reads.push(
                    vm.array_get(array, index as i32)
                        .map(Value::as_long)
                        .unwrap_or(0) as u64,
                );
            }
            words.append(&mut reads);
            words
        }
        None => Vec::new(),
    }
}

fn bitset_store(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    words: &[u64],
    min_bits: usize,
) -> Result<(), VmError> {
    let class = vm.class_of(this);
    let existing = vm
        .read_ref_field(this, class, "words", "[J")
        .and_then(|array| vm.array_length(array).ok())
        .unwrap_or(0);
    let mut length = min_bits.div_ceil(64);
    length = length.max(
        words
            .iter()
            .rposition(|word| *word != 0)
            .map_or(0, |i| i + 1),
    );
    // The JDK keeps the capacity once grown; only clone/serialization trim it.
    length = length.max(existing);
    let (declaring, field) = vm.find_field(class, "words", "[J")?;
    let array = vm.allocate_array_of(ArrayComponent::Long, length)?;
    for (index, word) in words.iter().take(length).enumerate() {
        vm.array_set(array, index as i32, Value::Long(*word as i64), false)?;
    }
    vm.set_instance_ref(this, declaring, field, array);
    if length > existing {
        // Growing beyond the initial capacity makes the size non-sticky.
        crate::lang::write_int_field(vm, this, "sticky", 0);
    }
    Ok(())
}

/// JDK `wordsInUse`: one past the last non-zero word.
fn bitset_in_use(words: &[u64]) -> usize {
    words
        .iter()
        .rposition(|word| *word != 0)
        .map_or(0, |i| i + 1)
}

/// JDK `trimToSize`: shrink the backing array to the words actually in use.
fn bitset_trim_to_size(vm: &mut Vm<'_>, this: ObjectRef) -> Result<(), VmError> {
    let words = bitset_words(vm, this);
    let in_use = bitset_in_use(&words);
    if in_use != words.len() {
        let class = vm.class_of(this);
        let (declaring, field) = vm.find_field(class, "words", "[J")?;
        let array = words_from_u64(vm, &words[..in_use])?;
        vm.set_instance_ref(this, declaring, field, array);
    }
    Ok(())
}

/// Build a BitSet from little-endian bytes (JDK `valueOf(byte[])` semantics).
fn bitset_from_bytes(vm: &mut Vm<'_>, bytes: &[u8]) -> Result<Value, VmError> {
    let mut n = bytes.len();
    while n > 0 && bytes[n - 1] == 0 {
        n -= 1;
    }
    let mut words = vec![0u64; n.div_ceil(8)];
    for (index, byte) in bytes.iter().take(n).enumerate() {
        words[index / 8] |= u64::from(*byte) << (8 * (index % 8));
    }
    let class = vm.resolve_class("java/util/BitSet")?;
    let instance = vm.new_instance(class)?;
    bitset_store(vm, instance, &words, 0)?;
    object(instance)
}

fn bit_set_range(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    from: usize,
    to: usize,
    value: bool,
) -> Result<(), VmError> {
    let mut words = bitset_words(vm, this);
    if from >= to {
        return Ok(());
    }
    words.resize(words.len().max(to.div_ceil(64)), 0);
    for bit in from..to {
        let word = bit / 64;
        let mask = 1u64 << (bit % 64);
        if value {
            words[word] |= mask;
        } else {
            words[word] &= !mask;
        }
    }
    bitset_store(vm, this, &words, 0)
}

/// JDK `BitSet` single-index validation: a negative index throws `IndexOutOfBoundsException`.
fn bitset_check_index(vm: &mut Vm<'_>, bit: i32) -> Result<usize, VmError> {
    if bit < 0 {
        return Err(vm.throw_new(
            "java/lang/IndexOutOfBoundsException",
            Some(&alloc::format!("bitIndex < 0: {bit}")),
        ));
    }
    Ok(bit as usize)
}

/// JDK `BitSet.checkRange`: validates a `[from, to)` bit range.
fn bitset_check_range(vm: &mut Vm<'_>, from: i32, to: i32) -> Result<(usize, usize), VmError> {
    if from < 0 {
        return Err(vm.throw_new(
            "java/lang/IndexOutOfBoundsException",
            Some(&alloc::format!("fromIndex < 0: {from}")),
        ));
    }
    if to < 0 {
        return Err(vm.throw_new(
            "java/lang/IndexOutOfBoundsException",
            Some(&alloc::format!("toIndex < 0: {to}")),
        ));
    }
    if from > to {
        return Err(vm.throw_new(
            "java/lang/IndexOutOfBoundsException",
            Some(&alloc::format!("fromIndex: {from} > toIndex: {to}")),
        ));
    }
    Ok((from as usize, to as usize))
}

