fn entry_field(vm: &Vm<'_>, this: ObjectRef, name: &str) -> ObjectRef {
    vm.read_ref_field(this, vm.class_of(this), name, "Ljava/lang/Object;")
        .unwrap_or(ObjectRef::NULL)
}

pub(crate) fn object_hash(vm: &mut Vm<'_>, reference: ObjectRef) -> Result<i32, VmError> {
    if reference.is_null() {
        return Ok(0);
    }
    let (class, method) = vm.resolve_virtual_method(reference, "hashCode", "()I")?;
    Ok(vm
        .invoke_method(class, method, vec![Value::Ref(reference)])?
        .as_int())
}

fn values_equal(vm: &mut Vm<'_>, a: ObjectRef, b: ObjectRef) -> Result<bool, VmError> {
    keys_equal(vm, a, b)
}

/// Read a `Map.Entry` component through the interface so any entry implementation
/// (not just our own field-backed ones) can be compared.
fn entry_component(vm: &mut Vm<'_>, entry: ObjectRef, name: &str) -> Result<ObjectRef, VmError> {
    let (class, method) = vm.resolve_virtual_method(entry, name, "()Ljava/lang/Object;")?;
    Ok(vm
        .invoke_method(class, method, vec![Value::Ref(entry)])?
        .as_ref())
}

/// The `Map.Entry.equals` contract: another `Map.Entry` with equal key and value,
/// regardless of the concrete entry class.
fn map_entry_equals(vm: &mut Vm<'_>, this: ObjectRef, other: ObjectRef) -> Result<bool, VmError> {
    let entry_class = vm.resolve_class("java/util/Map$Entry")?;
    if other.is_null() || !vm.is_instance(other, entry_class) {
        return Ok(false);
    }
    let this_key = entry_component(vm, this, "getKey")?;
    let other_key = entry_component(vm, other, "getKey")?;
    if !values_equal(vm, this_key, other_key)? {
        return Ok(false);
    }
    let this_value = entry_component(vm, this, "getValue")?;
    let other_value = entry_component(vm, other, "getValue")?;
    values_equal(vm, this_value, other_value)
}

/// The map's entries as a `HashSet` of `Map.Entry` snapshots.
fn map_entry_set(vm: &mut Vm<'_>, map: ObjectRef) -> Result<Value, VmError> {
    let pairs = hash_map_pairs(vm, map);
    let set_class = vm.resolve_class("java/util/HashSet")?;
    let set = vm.new_instance(set_class)?;
    let set_map = new_hash_map(vm)?;
    let (declaring, field) = vm.find_field(set_class, "map", "Ljava/util/HashMap;")?;
    vm.set_instance_ref(set, declaring, field, set_map);
    let present = hash_set_present(vm)?;
    for (key, value) in pairs {
        let entry = new_entry(vm, key, value)?;
        hash_map_call(
            vm,
            set_map,
            "put",
            "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",
            &[Value::Ref(entry), Value::Ref(present)],
        )?;
    }
    object(set)
}

pub(crate) fn new_entry(
    vm: &mut Vm<'_>,
    key: ObjectRef,
    value: ObjectRef,
) -> Result<ObjectRef, VmError> {
    let class = vm.resolve_class("java/util/OxjvmEntry")?;
    let instance = vm.new_instance(class)?;
    let (declaring, field) = vm.find_field(class, "key", "Ljava/lang/Object;")?;
    vm.set_instance_ref(instance, declaring, field, key);
    let (declaring, field) = vm.find_field(class, "value", "Ljava/lang/Object;")?;
    vm.set_instance_ref(instance, declaring, field, value);
    Ok(instance)
}

/// An entry snapshot whose `setValue` throws `UnsupportedOperationException`, as returned by
/// the `SequencedMap` end operations.
pub(crate) fn new_entry_immutable(
    vm: &mut Vm<'_>,
    key: ObjectRef,
    value: ObjectRef,
) -> Result<ObjectRef, VmError> {
    let instance = new_entry(vm, key, value)?;
    crate::lang::write_int_field(vm, instance, "immutable", 1);
    Ok(instance)
}

