fn currency_numeric_code(code: &str) -> i32 {
    ISO_4217
        .iter()
        .find(|(name, _)| *name == code)
        .map_or(-1, |(_, numeric)| *numeric)
}

/// ISO 4217 minor units that differ from the default of 2, per the JDK table.
const FRACTION_DIGITS: &[(&str, i32)] = &[
    ("ADP", 0),
    ("BHD", 3),
    ("BIF", 0),
    ("CLF", 4),
    ("CLP", 0),
    ("DJF", 0),
    ("GNF", 0),
    ("IQD", 3),
    ("ISK", 0),
    ("JOD", 3),
    ("JPY", 0),
    ("KMF", 0),
    ("KRW", 0),
    ("KWD", 3),
    ("LYD", 3),
    ("OMR", 3),
    ("PYG", 0),
    ("RWF", 0),
    ("TND", 3),
    ("UGX", 0),
    ("UYI", 0),
    ("VND", 0),
    ("VUV", 0),
    ("XAF", 0),
    ("XAG", -1),
    ("XAU", -1),
    ("XBA", -1),
    ("XBB", -1),
    ("XBC", -1),
    ("XBD", -1),
    ("XDR", -1),
    ("XFO", -1),
    ("XFU", -1),
    ("XOF", 0),
    ("XPD", -1),
    ("XPF", 0),
    ("XPT", -1),
    ("XSU", -1),
    ("XTS", -1),
    ("XUA", -1),
    ("XXX", -1),
];

fn currency_fraction_digits(code: &str) -> i32 {
    FRACTION_DIGITS
        .iter()
        .find(|(name, _)| *name == code)
        .map_or(2, |(_, digits)| *digits)
}

fn available_currencies(vm: &mut Vm<'_>) -> Result<Vec<ObjectRef>, VmError> {
    ISO_4217
        .iter()
        .map(|(code, _)| Ok(new_currency(vm, code)?.as_ref()))
        .collect()
}

