// -------------------------------------------------------------------------------------------
// Calendar / GregorianCalendar
// -------------------------------------------------------------------------------------------

const MILLIS_PER_DAY: i64 = 86_400_000;
const MILLIS_PER_HOUR: i64 = 3_600_000;

fn calendar_is_leap(year: i64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

fn calendar_days_in_month(year: i64, month: i64) -> i64 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if calendar_is_leap(year) => 29,
        2 => 28,
        _ => 30,
    }
}

#[derive(Clone, Copy)]
struct CalendarFields {
    year: i64,
    month: i64,
    day: i64,
    hour: i64,
    minute: i64,
    second: i64,
    millisecond: i64,
}

fn calendar_fields_from_millis(time: i64) -> CalendarFields {
    let days = time.div_euclid(MILLIS_PER_DAY);
    let of_day = time.rem_euclid(MILLIS_PER_DAY);
    let (year, month, day) = civil_from_days(days);
    CalendarFields {
        year,
        month: i64::from(month),
        day: i64::from(day),
        hour: of_day / MILLIS_PER_HOUR,
        minute: of_day / 60_000 % 60,
        second: of_day / 1_000 % 60,
        millisecond: of_day % 1_000,
    }
}

fn calendar_millis_from_fields(fields: CalendarFields) -> i64 {
    // The JDK multiplies in plain long arithmetic, which wraps on overflow
    // instead of saturating (GregorianCalendar.computeTime).
    days_from_civil(fields.year, fields.month, fields.day)
        .wrapping_mul(MILLIS_PER_DAY)
        .wrapping_add(fields.hour * MILLIS_PER_HOUR)
        .wrapping_add(fields.minute * 60_000)
        .wrapping_add(fields.second * 1_000)
        .wrapping_add(fields.millisecond)
}

fn calendar_day_of_week(time: i64) -> i64 {
    let days = time.div_euclid(MILLIS_PER_DAY);
    ((days + 4).rem_euclid(7)) + 1
}

fn calendar_day_of_year(time: i64) -> i64 {
    let fields = calendar_fields_from_millis(time);
    let first = days_from_civil(fields.year, 1, 1);
    let days = time.div_euclid(MILLIS_PER_DAY);
    days - first + 1
}

/// First day of week and minimal days in the first week for a locale, matching
/// the CLDR data the JDK uses (1 = Sunday .. 7 = Saturday).
fn locale_week_params(language: &str, country: &str) -> (i32, i32) {
    match (language, country) {
        ("en", "GB") => return (2, 4),
        ("en", "AU") | ("en", "NZ") => return (2, 1),
        ("pt", "BR") => return (1, 1),
        ("es", "MX") | ("es", "US") => return (1, 1),
        ("fr", "CA") => return (1, 1),
        _ => {}
    }
    match language {
        "de" | "fr" | "it" | "es" | "nl" | "da" | "sv" | "no" | "nb" | "nn" | "fi" | "pl"
        | "ru" | "el" | "cs" | "hu" | "bg" | "sk" | "ca" | "et" | "lt" | "ga" | "cy" | "eu"
        | "gl" | "fo" | "lb" | "rm" | "fy" | "br" | "co" | "oc" | "an" | "ast" | "wa" | "li"
        | "se" | "smn" | "sms" | "dsb" | "hsb" => (2, 4),
        "tr" | "ro" | "hr" | "sl" | "uk" | "sr" | "lv" | "vi" | "ms" | "si" | "ka" | "hy"
        | "az" | "kk" | "uz" | "mn" | "sq" | "mk" | "bs" | "be" | "kl" | "zh" => (2, 1),
        "pt" | "is" => (1, 4),
        "fa" => (7, 1),
        _ => (1, 1),
    }
}

/// Week parameters of a given locale, falling back to Sunday/1.
fn locale_week_params_of(vm: &mut Vm<'_>, locale: ObjectRef) -> (i32, i32) {
    if locale.is_null() {
        return (1, 1);
    }
    let lc = vm.class_of(locale);
    let language = vm
        .read_ref_field(locale, lc, "language", "Ljava/lang/String;")
        .unwrap_or(ObjectRef::NULL);
    let country = vm
        .read_ref_field(locale, lc, "country", "Ljava/lang/String;")
        .unwrap_or(ObjectRef::NULL);
    let language = vm.string_or_empty(language);
    let country = vm.string_or_empty(country);
    locale_week_params(&language, &country)
}

/// Week parameters of the current default locale, falling back to Sunday/1.
fn calendar_default_week_params(vm: &mut Vm<'_>) -> (i32, i32) {
    let Some(class) = vm.resolve_class_lenient_pub("java/util/Locale") else {
        return (1, 1);
    };
    let locale = vm
        .read_static_ref_if_set(class, "defaultLocale", "Ljava/util/Locale;")
        .or_else(|| vm.read_static_ref_if_set(class, "US", "Ljava/util/Locale;"))
        .unwrap_or(ObjectRef::NULL);
    locale_week_params_of(vm, locale)
}

/// Override the week parameters of an already-initialized calendar from a locale.
fn calendar_apply_locale(vm: &mut Vm<'_>, this: ObjectRef, locale: ObjectRef) {
    let (first_day, minimal_days) = locale_week_params_of(vm, locale);
    for (name, value) in [
        ("firstDayOfWeek", first_day),
        ("minimalDaysInFirstWeek", minimal_days),
    ] {
        if let Some((declaring, field)) = vm.find_field_opt(vm.class_of(this), name, "I") {
            vm.set_instance_int(this, declaring, field, value);
        }
    }
}

fn calendar_init(vm: &mut Vm<'_>, this: ObjectRef, time: i64) -> Result<(), VmError> {
    crate::lang::write_long_field(vm, this, "time", time);
    calendar_mark_all(vm, this);
    calendar_set_time_set(vm, this);
    if let Some((declaring, field)) = vm.find_field_opt(vm.class_of(this), "lenient", "Z") {
        vm.set_instance_int(this, declaring, field, 1);
    }
    let (first_day, minimal_days) = calendar_default_week_params(vm);
    for (name, value) in [
        ("firstDayOfWeek", first_day),
        ("minimalDaysInFirstWeek", minimal_days),
    ] {
        if let Some((declaring, field)) = vm.find_field_opt(vm.class_of(this), name, "I") {
            vm.set_instance_int(this, declaring, field, value);
        }
    }
    let zone_class = vm.resolve_class("java/util/TimeZone")?;
    let zone = vm.new_instance(zone_class)?;
    let (declaring, field) = vm.find_field(zone_class, "id", "Ljava/lang/String;")?;
    let id = vm.make_string("GMT")?;
    vm.set_instance_ref(zone, declaring, field, id);
    if let Some((declaring, field)) =
        vm.find_field_opt(vm.class_of(this), "timeZone", "Ljava/util/TimeZone;")
    {
        vm.set_instance_ref(this, declaring, field, zone);
    }
    Ok(())
}

fn calendar_time(vm: &Vm<'_>, this: ObjectRef) -> i64 {
    crate::lang::read_long_field(vm, this, "time")
}

fn calendar_set_time(vm: &mut Vm<'_>, this: ObjectRef, time: i64) {
    crate::lang::write_long_field(vm, this, "time", time);
}

fn calendar_mark(vm: &mut Vm<'_>, this: ObjectRef, field: i32) {
    if !(0..17).contains(&field) {
        return;
    }
    let bits = crate::lang::read_int_field(vm, this, "setFields");
    crate::lang::write_int_field(vm, this, "setFields", bits | (1 << field));
}

fn calendar_mark_all(vm: &mut Vm<'_>, this: ObjectRef) {
    crate::lang::write_int_field(vm, this, "setFields", (1 << 17) - 1);
}

fn calendar_is_set(vm: &Vm<'_>, this: ObjectRef, field: i32) -> bool {
    if !(0..17).contains(&field) {
        return false;
    }
    crate::lang::read_int_field(vm, this, "setFields") & (1 << field) != 0
}

fn calendar_set_time_set(vm: &mut Vm<'_>, this: ObjectRef) {
    if let Some((declaring, field)) = vm.find_field_opt(vm.class_of(this), "isTimeSet", "Z") {
        vm.set_instance_int(this, declaring, field, 1);
    }
}

fn calendar_is_lenient(vm: &Vm<'_>, this: ObjectRef) -> bool {
    vm.read_instance_int_named(this, vm.class_of(this), "lenient", "Z")
        .unwrap_or(1)
        != 0
}

fn calendar_set_lenient(vm: &mut Vm<'_>, this: ObjectRef, value: bool) {
    if let Some((declaring, field)) = vm.find_field_opt(vm.class_of(this), "lenient", "Z") {
        vm.set_instance_int(this, declaring, field, i32::from(value));
    }
}

fn calendar_field_int(vm: &Vm<'_>, this: ObjectRef, name: &str) -> i32 {
    crate::lang::read_int_field(vm, this, name)
}

fn calendar_set_field_int(vm: &mut Vm<'_>, this: ObjectRef, name: &str, value: i32) {
    crate::lang::write_int_field(vm, this, name, value);
}

fn calendar_add(vm: &mut Vm<'_>, this: ObjectRef, field: i32, amount: i32) {
    let time = calendar_time(vm, this);
    let mut fields = calendar_fields_from_millis(time);
    match field {
        // ERA
        0 => {}
        // YEAR
        1 => {
            fields.year += i64::from(amount);
            let max_day = calendar_days_in_month(fields.year, fields.month);
            fields.day = fields.day.min(max_day);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // MONTH
        2 => {
            let total = fields.year * 12 + (fields.month - 1) + i64::from(amount);
            fields.year = total.div_euclid(12);
            fields.month = total.rem_euclid(12) + 1;
            let max_day = calendar_days_in_month(fields.year, fields.month);
            fields.day = fields.day.min(max_day);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // WEEK_OF_YEAR / WEEK_OF_MONTH / DAY_OF_WEEK_IN_MONTH
        3 | 4 | 8 => {
            calendar_set_time(
                vm,
                this,
                time.saturating_add(i64::from(amount) * 7 * MILLIS_PER_DAY),
            );
        }
        // DATE / DAY_OF_MONTH / DAY_OF_YEAR / DAY_OF_WEEK
        5..=7 => {
            calendar_set_time(
                vm,
                this,
                time.saturating_add(i64::from(amount) * MILLIS_PER_DAY),
            );
        }
        // AM_PM
        9 => {
            calendar_set_time(
                vm,
                this,
                time.saturating_add(i64::from(amount) * 12 * MILLIS_PER_HOUR),
            );
        }
        // HOUR / HOUR_OF_DAY
        10 | 11 => {
            calendar_set_time(
                vm,
                this,
                time.saturating_add(i64::from(amount) * MILLIS_PER_HOUR),
            );
        }
        // MINUTE
        12 => {
            calendar_set_time(vm, this, time.saturating_add(i64::from(amount) * 60_000));
        }
        // SECOND
        13 => {
            calendar_set_time(vm, this, time.saturating_add(i64::from(amount) * 1_000));
        }
        // MILLISECOND
        14 => {
            calendar_set_time(vm, this, time.saturating_add(i64::from(amount)));
        }
        _ => {}
    }
}

/// `Calendar.roll(field, amount)`: move within the field's own range without carrying into
/// larger fields (rolling December forward lands in January of the *same* year).
fn calendar_roll(vm: &mut Vm<'_>, this: ObjectRef, field: i32, amount: i32) {
    let time = calendar_time(vm, this);
    let mut fields = calendar_fields_from_millis(time);
    let amount = i64::from(amount);
    if amount == 0 {
        return;
    }
    match field {
        // MONTH: cycle within the year, clamping the day.
        2 => {
            let month = (fields.month - 1 + amount).rem_euclid(12) + 1;
            fields.month = month;
            let max_day = calendar_days_in_month(fields.year, month);
            fields.day = fields.day.min(max_day);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // WEEK_OF_YEAR: cycle through the weeks of the calendar year, keeping
        // the day of week and the year (GregorianCalendar.roll semantics).
        3 => {
            let year = fields.year;
            let dow = calendar_day_of_week(time);
            let first = calendar_first_day_of_week(vm, this);
            let dow_offset = (dow - first).rem_euclid(7);
            let of_day = time.rem_euclid(MILLIS_PER_DAY);
            let week_year = calendar_week_year(vm, this, time);
            let mut woy = i64::from(calendar_get(vm, this, 3));
            let start = calendar_week_one_start(vm, this, year);
            let mut max =
                (calendar_week_one_start(vm, this, year + 1) - start) / (7 * MILLIS_PER_DAY);
            let mut min = 1i64;
            let mut amount = amount;
            let mut new_woy = if week_year == year {
                let value = woy + amount;
                if value > min && value < max {
                    value
                } else {
                    // The current day of week must exist in week min / week max
                    // of this calendar year, otherwise shrink the wrap range.
                    let day1 = time - (woy - min) * 7 * MILLIS_PER_DAY;
                    if calendar_fields_from_millis(day1).year != year {
                        min += 1;
                    }
                    let day_max = time + (max - woy) * 7 * MILLIS_PER_DAY;
                    if calendar_fields_from_millis(day_max).year != year {
                        max -= 1;
                    }
                    calendar_rolled_value(woy, amount, min, max)
                }
            } else if week_year > year {
                // The date sits in week 1 of the next week-year; stay in this
                // calendar year by rolling from the last week.
                if amount < 0 {
                    amount += 1;
                }
                woy = max;
                calendar_rolled_value(woy, amount, min, max)
            } else {
                // The date sits in the last week of the previous week-year.
                if amount > 0 {
                    amount -= woy - max;
                }
                woy = min;
                calendar_rolled_value(woy, amount, min, max)
            };
            if new_woy == 1 && amount > 0 && calendar_invalid_week1(vm, this, year, dow) {
                new_woy += 1;
            }
            let new_time =
                start + (new_woy - 1) * 7 * MILLIS_PER_DAY + dow_offset * MILLIS_PER_DAY + of_day;
            calendar_set_time(vm, this, new_time);
        }
        // DATE / DAY_OF_MONTH: cycle within the month.
        5 => {
            let max_day = calendar_days_in_month(fields.year, fields.month);
            fields.day = (fields.day - 1 + amount).rem_euclid(max_day) + 1;
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // DAY_OF_WEEK: cycle within the week.
        7 => {
            let dow = calendar_day_of_week(time);
            let first = calendar_first_day_of_week(vm, this);
            let offset = (dow - first + amount).rem_euclid(7);
            let days = time.div_euclid(MILLIS_PER_DAY);
            let week_start = days - (dow - first).rem_euclid(7);
            let of_day = time.rem_euclid(MILLIS_PER_DAY);
            calendar_set_time(vm, this, (week_start + offset) * MILLIS_PER_DAY + of_day);
        }
        // HOUR_OF_DAY
        11 => {
            fields.hour = (fields.hour + amount).rem_euclid(24);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // HOUR (12-hour clock)
        10 => {
            fields.hour = (fields.hour + amount).rem_euclid(12);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // MINUTE
        12 => {
            fields.minute = (fields.minute + amount).rem_euclid(60);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // SECOND
        13 => {
            fields.second = (fields.second + amount).rem_euclid(60);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // MILLISECOND
        14 => {
            fields.millisecond = (fields.millisecond + amount).rem_euclid(1000);
            calendar_set_time(vm, this, calendar_millis_from_fields(fields));
        }
        // Larger fields have no smaller range to wrap within; fall back to add.
        _ => calendar_add(vm, this, field, amount as i32),
    }
}

/// Wrap `value + amount` into the inclusive range `[min, max]` (Calendar.getRolledValue).
fn calendar_rolled_value(value: i64, amount: i64, min: i64, max: i64) -> i64 {
    let range = max - min + 1;
    if range <= 0 {
        return value;
    }
    let amount = amount % range;
    let mut n = value + amount;
    if n > max {
        n -= range;
    } else if n < min {
        n += range;
    }
    n
}

/// Whether week 1 of `year` is a valid first week but does not contain `dow`
/// within the year (GregorianCalendar.isInvalidWeek1).
fn calendar_invalid_week1(vm: &Vm<'_>, this: ObjectRef, year: i64, dow: i64) -> bool {
    let jan1 = days_from_civil(year, 1, 1);
    let jan1_dow = ((jan1 + 4).rem_euclid(7)) + 1;
    let first = calendar_first_day_of_week(vm, this);
    let days_in_first_week = if first <= jan1_dow {
        7 - jan1_dow + first
    } else {
        first - jan1_dow
    };
    let end_dow = if first == 1 { 7 } else { first - 1 };
    let in_min_week = if end_dow >= jan1_dow {
        dow >= jan1_dow && dow <= end_dow
    } else {
        dow >= jan1_dow || dow <= end_dow
    };
    days_in_first_week >= calendar_minimal_days(vm, this) && !in_min_week
}

/// The configured first day of the week (1 = Sunday .. 7 = Saturday), defaulting to Sunday.
fn calendar_first_day_of_week(vm: &Vm<'_>, this: ObjectRef) -> i64 {
    let value = vm
        .read_instance_int_named(this, vm.class_of(this), "firstDayOfWeek", "I")
        .unwrap_or(0);
    if (1..=7).contains(&value) {
        i64::from(value)
    } else {
        1
    }
}

/// The configured minimal days in the first week, defaulting to 1.
fn calendar_minimal_days(vm: &Vm<'_>, this: ObjectRef) -> i64 {
    let value = vm
        .read_instance_int_named(this, vm.class_of(this), "minimalDaysInFirstWeek", "I")
        .unwrap_or(0);
    if (1..=7).contains(&value) {
        i64::from(value)
    } else {
        1
    }
}

/// Midnight of the first day of the week containing `time`.
fn calendar_week_start(vm: &Vm<'_>, this: ObjectRef, time: i64) -> i64 {
    let days = time.div_euclid(MILLIS_PER_DAY);
    let dow = ((days + 4).rem_euclid(7)) + 1;
    let first = calendar_first_day_of_week(vm, this);
    (days - (dow - first).rem_euclid(7)) * MILLIS_PER_DAY
}

/// The week-year a time belongs to: the year whose week-1 span contains the week.
fn calendar_week_year(vm: &Vm<'_>, this: ObjectRef, time: i64) -> i64 {
    let week_start = calendar_week_start(vm, this, time);
    let year = civil_from_days(time.div_euclid(MILLIS_PER_DAY)).0;
    if week_start < calendar_week_one_start(vm, this, year) {
        year - 1
    } else if week_start >= calendar_week_one_start(vm, this, year + 1) {
        year + 1
    } else {
        year
    }
}

/// Midnight of the first day of week 1 of the given week-year: the first week
/// holding at least `minimalDaysInFirstWeek` days of that year.
fn calendar_week_one_start(vm: &Vm<'_>, this: ObjectRef, week_year: i64) -> i64 {
    let jan1 = days_from_civil(week_year, 1, 1);
    let dow = ((jan1 + 4).rem_euclid(7)) + 1;
    let first = calendar_first_day_of_week(vm, this);
    let offset = (dow - first).rem_euclid(7);
    let minimal = calendar_minimal_days(vm, this);
    let mut start = (jan1 - offset) * MILLIS_PER_DAY;
    if 7 - offset < minimal {
        start += 7 * MILLIS_PER_DAY;
    }
    start
}

/// Midnight of the first day of week 1 of the given calendar month: the first
/// week holding at least `minimalDaysInFirstWeek` days of that month.
fn calendar_month_week_one_start(vm: &Vm<'_>, this: ObjectRef, year: i64, month: i64) -> i64 {
    let first_day = days_from_civil(year, month, 1);
    let dow = ((first_day + 4).rem_euclid(7)) + 1;
    let first = calendar_first_day_of_week(vm, this);
    let offset = (dow - first).rem_euclid(7);
    let minimal = calendar_minimal_days(vm, this);
    let mut start = (first_day - offset) * MILLIS_PER_DAY;
    if 7 - offset < minimal {
        start += 7 * MILLIS_PER_DAY;
    }
    start
}

fn calendar_get(vm: &Vm<'_>, this: ObjectRef, field: i32) -> i32 {
    let time = calendar_time(vm, this);
    let fields = calendar_fields_from_millis(time);
    match field {
        0 => i32::from(fields.year > 0),
        1 => fields.year as i32,
        2 => fields.month as i32 - 1,
        3 => {
            let week_year = calendar_week_year(vm, this, time);
            let start = calendar_week_one_start(vm, this, week_year);
            let week_start = calendar_week_start(vm, this, time);
            ((week_start - start) / (7 * MILLIS_PER_DAY) + 1) as i32
        }
        4 => ((fields.day - 1) / 7 + 1) as i32,
        5 => fields.day as i32,
        6 => calendar_day_of_year(time) as i32,
        7 => calendar_day_of_week(time) as i32,
        8 => ((fields.day - 1) / 7 + 1) as i32,
        9 => i32::from(fields.hour >= 12),
        10 => (fields.hour % 12) as i32,
        11 => fields.hour as i32,
        12 => fields.minute as i32,
        13 => fields.second as i32,
        14 => fields.millisecond as i32,
        15 | 16 => 0,
        17 => 17,
        _ => 0,
    }
}

/// Lenient month normalization: month 0 is December of the previous year and
/// month 13 is January of the next year (`BaseCalendar.normalizeMonth`).
fn calendar_normalize_month(year: i64, month: i64) -> (i64, i64) {
    let total = year * 12 + (month - 1);
    (total.div_euclid(12), total.rem_euclid(12) + 1)
}

fn calendar_set_components(
    vm: &mut Vm<'_>,
    this: ObjectRef,
    year: i64,
    month: i64,
    day: i64,
    hour: i64,
    minute: i64,
    second: i64,
) {
    // Lenient mode carries out-of-range days into the following months
    // instead of clamping; days_from_civil is linear in the day argument.
    let (year, month) = calendar_normalize_month(year, month);
    let fields = CalendarFields {
        year,
        month,
        day,
        hour,
        minute,
        second,
        millisecond: 0,
    };
    calendar_set_time(vm, this, calendar_millis_from_fields(fields));
}

fn calendar_get_time_value(vm: &mut Vm<'_>, time: i64) -> Result<Value, VmError> {
    let class = vm.resolve_class("java/util/Date")?;
    let instance = vm.new_instance(class)?;
    if let Some((declaring, field)) = vm.find_field_opt(class, "time", "J") {
        vm.set_instance_long(instance, declaring, field, time);
    }
    object(instance)
}

fn calendar_instance(vm: &mut Vm<'_>) -> Result<Value, VmError> {
    let class = vm.resolve_class("java/util/GregorianCalendar")?;
    let instance = vm.new_instance(class)?;
    let now = vm.host_time_millis();
    calendar_init(vm, instance, now)?;
    object(instance)
}

