/// Least maximum of `WEEK_OF_MONTH` indexed by `[firstDayOfWeek-1][minimalDays-1]`.
/// The value depends only on the week configuration (not the date), matching the
/// JDK's GregorianCalendar bounds for every first-day/minimal-days combination.
const WEEK_OF_MONTH_LEAST: [[i32; 7]; 7] = [
    [3, 3, 3, 3, 3, 3, 2],
    [3, 3, 3, 3, 3, 3, 3],
    [4, 3, 3, 3, 3, 3, 3],
    [4, 4, 3, 3, 3, 3, 3],
    [4, 4, 4, 3, 3, 3, 3],
    [4, 4, 4, 4, 3, 3, 3],
    [3, 3, 3, 3, 3, 2, 2],
];

fn calendar_minimum(field: i32) -> i32 {
    match field {
        0 => 0,
        1 => 1,
        2 | 8 | 9 | 10 => 0,
        3 | 4 => 1,
        5..=7 => 1,
        11..=14 => 0,
        15 => -50400000,
        16 => 0,
        17 => 17,
        _ => 0,
    }
}

fn calendar_maximum(field: i32) -> i32 {
    match field {
        0 => 1,
        1 => 292_278_994,
        2 => 11,
        3 => 54,
        4 => 6,
        5 => 31,
        6 => 366,
        7 => 7,
        8 => 6,
        9 => 1,
        10 => 11,
        11 => 23,
        12 | 13 => 59,
        14 => 999,
        15 => 50400000,
        16 => 7200000,
        17 => 17,
        _ => 0,
    }
}

const fn calendar_constant(name: &'static str, value: i32) -> oxjvm_vm::NativeFieldDef {
    field(
        name,
        "I",
        ACC_PUBLIC | ACC_STATIC | ACC_FINAL,
        Some(oxjvm_vm::NativeConstant::Int(value)),
    )
}

